# Illustrative example, spec version v0.2. Decoded view; hashes and signatures shortened.
# Abridged OpenID4VP request through the Digital Credentials API, with the decoded delegate entry of transaction_data.
{
  "protocol": "openid4vp-v1-unsigned",
  "data": {
    "response_type": "vp_token",
    "response_mode": "dc_api",
    "nonce": "5f0c...e2a",
    "dcql_query": {
      "credentials": [
        {
          "id": "dpc_credential",
          "format": "dc+sd-jwt",
          "meta": {
            "vct_values": [
              "com.emvco.dpc"
            ]
          },
          "claims": [
            {
              "path": [
                "card_last_four"
              ]
            },
            {
              "path": [
                "card_network_code"
              ]
            },
            {
              "path": [
                "credential_id"
              ]
            }
          ]
        }
      ]
    },
    "transaction_data": [
      "<base64url payment_card entry for the confirmation screen>",
      "<base64url delegate entry, decoded below>"
    ]
  }
}
# decoded delegate entry
{
  "type": "delegate",
  "format": "dc+sd-jwt",
  "credential_ids": [
    "dpc_credential"
  ],
  "transaction_data_hashes_alg": [
    "sha-256"
  ],
  "delegate_payload": [
    {
      "vct": "mandate.checkout.1",
      "checkout_jwt": "eyJhbGciOiJFUzI1NiIs...",
      "checkout_hash": "Nv3Wq...X8"
    },
    {
      "vct": "mandate.payment.1",
      "transaction_id": "Nv3Wq...X8",
      "payee": {
        "id": "merchant_1",
        "name": "Example Outdoor Store"
      },
      "payment_amount": {
        "amount": 27999,
        "currency": "USD"
      },
      "payment_instrument": {
        "id": "pi_7f3c",
        "type": "card",
        "description": "Card ending 4242"
      }
    }
  ]
}
